{"path": "math_test.go", "content": "package math

import "testing"

func TestMultiply(t *testing.T) {
	// 正常测试用例
	testCases := []struct {
		name     string
		a        int
		b        int
		expected int
	}{
		{
			name:     "positive numbers",
			a:        3,
			b:        4,
			expected: 12,
		},
		{
			name:     "negative numbers",
			a:        -2,
			b:        -5,
			expected: 10,
		},
		{
			name:     "positive and negative",
			a:        6,
			b:        -3,
			expected: -18,
		},
		{
			name:     "zero with positive",
			a:        0,
			b:        7,
			expected: 0,
		},
		{
			name:     "zero with negative",
			a:        -8,
			b:        0,
			expected: 0,
		},
		{
			name:     "both zero",
			a:        0,
			b:        0,
			expected: 0,
		},
		{
			name:     "large numbers",
			a:        1000,
			b:        2000,
			expected: 2000000,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			result := Multiply(tc.a, tc.b)
			if result != tc.expected {
				t.Errorf("Multiply(%d, %d) = %d, want %d", tc.a, tc.b, result, tc.expected)
			}
		})
	}
}

// 边界测试用例
func TestMultiply_Boundary(t *testing.T) {
	// 测试最大和最小 int 值
	testCases := []struct {
		name     string
		a        int
		b        int
		expected int
	}{
		{
			name:     "max int",
			a:        1<<31 - 1,
			b:        1,
			expected: 1<<31 - 1,
		},
		{
			name:     "min int",
			a:        -1 << 31,
			b:        1,
			expected: -1 << 31,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			result := Multiply(tc.a, tc.b)
			if result != tc.expected {
				t.Errorf("Multiply(%d, %d) = %d, want %d", tc.a, tc.b, result, tc.expected)
			}
		})
	}
}

// 性能测试（可选）
func BenchmarkMultiply(b *testing.B) {
	for i := 0; i < b.N; i++ {
		Multiply(123, 456)
	}
}"}
